// The real model's first inference request: Ripple-65B-Preview (the release's
// AD-Q4_K_M GGUF and DFlash2 draft) loaded through the engine's real
// machinery, a prompt prefilled, and tokens generated by prefilling the grown
// sequence again — one pass over the weights per token, which measures the
// single-token path's cost directly. The request's tokens come from a file
// (one id per line) that the release's tokenizer wrote; the harness prints
// the sampled ids so the caller can decode them.
//
// usage: ripple-real-test METALLIB MODEL_ROOT TOKENS_FILE STEPS
#include "TestChecks.hpp"
#include "ClaimScope.hpp"
#include "engine/MemoryGovernor.hpp"
#include "model/ModelFactory.hpp"
#include "model/Ripple.hpp"
#include "model/RuntimeArenas.hpp"
#include "ops/ExecutionPlans.hpp"
#include "ops/PageStorage.hpp"
#include "ops/Linear.hpp"
#include "ops/RowCopy.hpp"
#include "ops/RoPE.hpp"

#import <Foundation/Foundation.h>

#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <span>
#include <stdexcept>
#include <vector>

namespace {

using splash::metal::BufferStorage;
using splash::metal::CommandGraph;
using splash::metal::MetalBackend;
using splash::metal::MetalBuffer;
using splash::model::LoadedModel;
using splash::model::QwenTarget;
using splash::model::QwenTargetPrefillBuffers;
using splash::model::QwenTargetPrefillChunk;
using splash::model::QwenTargetPrefillSequence;
using splash::model::QwenTargetRequest;
using splash::model::RuntimeGeometry;
using splash::model::SpilledKvReads;
using splash::ops::ExecutionPlans;
using splash::test::require;

using namespace splash;

constexpr uint32_t kLayers = 80;
constexpr uint32_t kHidden = 5120;
constexpr uint32_t kVocab = 100352;
constexpr uint32_t kQueryHeads = 80;
constexpr uint32_t kKvHeads = 8;
constexpr uint32_t kHeadDim = 128;
constexpr uint32_t kPairs = 64;
constexpr uint32_t kIntermediate = 40960;
constexpr uint32_t kWindow = 1024;
constexpr float kEmbedScale = 71.5541763305664F;
constexpr float kClamp = 20.0F;
constexpr uint32_t kBos = 100257;

// The family's 4+1 pattern: four sliding attention layers, then a full one,
// whose RoPE the full layers leave out (NoPE).
std::pair<std::vector<uint64_t>, std::vector<uint64_t>> attentionMasks() {
  std::vector<uint64_t> sliding(2, 0), full(2, 0);
  for (uint32_t layer = 0; layer < kLayers; ++layer) {
    auto &mask = layer % 5 == 4 ? full : sliding;
    mask[layer / 64] |= 1ULL << (layer % 64);
  }
  return {sliding, full};
}

MetalBuffer upload(MetalBackend &backend, const std::vector<uint32_t> &values, const char *label) {
  MetalBuffer buffer = backend.allocateBuffer(values.size() * 4, BufferStorage::Shared, label);
  std::memcpy(buffer.contents(), values.data(), values.size() * 4);
  return buffer;
}

// One prefill of the sequence's rows, ending with the head over every row;
// returns the logits buffer, fp32 rows of kVocab.
MetalBuffer prefill(MetalBackend &backend, LoadedModel &model, QwenTarget *target,
                    const ExecutionPlans &operators, kv::PageStorage &pages,
                    const std::vector<uint32_t> &pageIds, const std::vector<uint32_t> &tokens,
                    const model::DecodeArena &decodeArena, std::vector<double> &seconds) {
  MetalBuffer logits;
  model::withPrefillArena(backend, model, operators, kv::Format::BFloat16,
                           [&](const QwenTargetPrefillBuffers &buffers) {
    const auto began = std::chrono::steady_clock::now();
    CommandGraph graph;
    std::vector<uint32_t> positions;
    positions.reserve(tokens.size() * 3);
    for (uint32_t index = 0; index < tokens.size(); ++index)
      positions.insert(positions.end(), {index, index, index});
    const MetalBuffer positionBuffer = upload(backend, positions, "rope positions");
    const MetalBuffer none = backend.allocateBuffer(4, BufferStorage::Shared, "unbound");
    ops::RoPE::addTables(graph, positionBuffer, none, buffers.ropeInverseFrequencies, none, buffers.ropeCos,
                         buffers.ropeSin, none, none,
                         {.target_rows = static_cast<uint32_t>(tokens.size()), .draft_rows = 0, .target_scale = 1.0F},
                         static_cast<uint32_t>(tokens.size()), kPairs);
    const MetalBuffer tokenBuffer = upload(backend, tokens, "prefill tokens");
    target->addEmbedding(graph, tokenBuffer, buffers.hidden[0], static_cast<uint32_t>(tokens.size()));

    QwenTargetPrefillSequence sequence;
    sequence.lane = 0;
    sequence.rowBegin = 0;
    sequence.rows = static_cast<uint32_t>(tokens.size());
    sequence.tokens = std::span<const uint32_t>(tokens);
    sequence.request = QwenTargetRequest{
        std::span<const uint32_t>(tokens),
        [](uint64_t logical) { return std::array<uint32_t, 3>{uint32_t(logical), uint32_t(logical), uint32_t(logical)}; }};
    sequence.attentionStride = (sequence.rows + kv::kPageTokens - 1) / kv::kPageTokens * kv::kPageTokens;
    sequence.queryOffset = 0;
    sequence.kvOffset = 0;
    sequence.chunk = ops::PagedAttention::prefillParams(0, sequence.rows, sequence.attentionStride,
                                                        static_cast<uint32_t>(pageIds.size()));
    MetalBuffer table =
        backend.allocateBuffer(pageIds.size() * sizeof(SplashKvPage), BufferStorage::Shared, "page table");
    pages.writeEntries(pageIds, 0, table);
    sequence.pageTable = table;

    QwenTargetPrefillChunk chunk;
    chunk.buffers = buffers;
    chunk.sequences = {&sequence, 1};
    chunk.rows = sequence.rows;

    SpilledKvReads spilled;
    const std::vector<MetalBuffer> finalHidden =
        target->addPrefill(graph, {&chunk, 1}, pages, spilled, {0, kLayers});

    // The head covers a verify tile's rows; the last row carries the
    // request's next token, copied into the tile's first row.
    constexpr uint32_t kVerifyRows = SPLASH_TARGET_VERIFY_ROWS;
    MetalBuffer headInput =
        backend.allocateBuffer(uint64_t{kVerifyRows} * kHidden * 2, BufferStorage::Shared, "head input");
    std::memset(headInput.contents(), 0, headInput.sizeBytes());
    MetalBuffer finalHidden0 =
        backend.allocateBuffer(uint64_t{kVerifyRows} * kHidden * 2, BufferStorage::Shared, "final hidden");
    logits = backend.allocateBuffer(uint64_t{kVerifyRows} * kVocab * 4, BufferStorage::Shared, "logits");
    splash::ops::RowCopy::add(graph, finalHidden[0], {sequence.rows - 1, kHidden, 0}, headInput, {0, kHidden, 0}, 1,
                              kHidden);
    target->addHeadBatch(graph, headInput, finalHidden0, logits, 1, decodeArena.linearScratch());
    static_cast<void>(backend.submitCommandAsync(graph.dispatches()).wait());
    seconds.push_back(std::chrono::duration<double>(std::chrono::steady_clock::now() - began).count());
  });
  return logits;
}

} // namespace

int main(int argc, char **argv) {
  try {
    if (argc != 5) throw std::invalid_argument("usage: ripple-real-test METALLIB MODEL_ROOT TOKENS_FILE STEPS");
    MetalBackend backend(argv[1]);
    const std::filesystem::path root(argv[2]);
    std::vector<uint32_t> tokens{kBos};
    {
      std::ifstream in(argv[3]);
      uint32_t id = 0;
      while (in >> id) tokens.push_back(id);
    }
    const uint32_t steps = static_cast<uint32_t>(std::stoul(argv[4]));

    splash::model::RippleLayout layout;
    layout.nativeContextTokens = 262144;
    layout.layers = kLayers;
    layout.hiddenSize = kHidden;
    layout.vocabularySize = kVocab;
    layout.attentionWidth = kQueryHeads * kHeadDim;
    layout.attentionQueryHeads = kQueryHeads;
    layout.attentionKvHeads = kKvHeads;
    layout.attentionHeadDimension = kHeadDim;
    layout.rotaryPairs = kPairs;
    layout.rotaryTheta = 10000.0F;
    layout.intermediateSize = kIntermediate;
    layout.embeddingScale = kEmbedScale;
    layout.swigluClamp = kClamp;
    layout.valueResidual = true;
    layout.postFfnNorm = true;
    layout.maskToken = 100278;
    layout.stopTokens = {100265, kBos};
    const auto [sliding, full] = attentionMasks();
    layout.slidingLayers = {sliding[0], sliding[1]};
    layout.unrotatedLayers = {full[0], full[1]};
    layout.fullAttentionPeriod = 1;
    layout.slidingWindow = kWindow;
    layout.ffnKind = splash::model::QwenFfnKind::Dense;
    layout.packedFullWidth = 2 * (kQueryHeads * kHeadDim) + 2 * (kKvHeads * kHeadDim);

    const std::vector<uint32_t> draftLayers{1, 20, 39, 58, 77};
    const splash::model::DFlashDraftLayout draft = splash::model::draftLayout(
        kHidden, kVocab, 5, kIntermediate, 10000.0F, draftLayers, SPLASH_DRAFT_VARIANTS[1]);
    const splash::model::ModelDescriptor descriptor = splash::model::makeModelDescriptor(
        "ripple-65b-real", layout, draft, {.outputHiddenSize = kHidden},
        splash::model::TargetSource::Gguf, splash::model::VisionSource::None);
    require(descriptor.valid(), "the real model's descriptor is not valid");

    const auto loadBegan = std::chrono::steady_clock::now();
    LoadedModel model = splash::model::loadModel(backend, root, descriptor);
    const double loadSeconds = std::chrono::duration<double>(std::chrono::steady_clock::now() - loadBegan).count();
    std::cout << "loaded in " << loadSeconds << " s\n";

    const ExecutionPlans operators(backend.capabilities(), ops::Int8Activations::Off);
    const RuntimeGeometry geometry =
        RuntimeGeometry::from(model, kv::Format::BFloat16, splash::ops::GdnStateFormat::Float32);
    auto target = std::visit(
        [&](const auto &weights) {
          return makeQwenTarget(weights, geometry.target, backend, operators, geometry.prefillChunks);
        },
        model.target);

    const model::DecodeArena decodeArena(backend, geometry, operators);

    engine::MemoryGovernor governor(backend, backend.capabilities().recommendedMaxWorkingSetBytes, 1, 1,
                                    engine::queryHostMemory, 0);
    const test::ClaimScope claim(governor, engine::ClaimClass::Floor);
    const kv::Layout kvLayout = model.targetKvLayout(kv::Format::BFloat16);
    const uint32_t extent = kvLayout.minimumExtentPages();
    kv::PageStorage pages(backend, governor.allocationAdmission(), kvLayout, 2 * extent, extent);
    require(static_cast<bool>(pages.allocateExtent(0)), "the real run's first extent did not allocate");
    require(static_cast<bool>(pages.allocateExtent(1)), "the real run's second extent did not allocate");
    const std::vector<uint32_t> pageIds{0, 1};

    std::vector<double> seconds;
    MetalBuffer logits = prefill(backend, model, target.get(), operators, pages, pageIds, tokens, decodeArena, seconds);
    for (uint32_t step = 0; step < steps; ++step) {
      const auto *values = static_cast<const float *>(logits.contents());
      uint32_t best = 0;
      double bestValue = -INFINITY;
      for (uint32_t token = 0; token < kVocab; ++token) {
        const double value = values[token];
        if (value > bestValue) bestValue = value, best = token;
      }
      std::cout << "step " << step << ": token " << best << " (" << bestValue << ")\n";
      if (best == 100265 || best == kBos) break;
      tokens.push_back(best);
      if (tokens.size() > 2 * kv::kPageTokens) {
        // The sequence outgrew the two pages' 64 tokens: stop, the point is
        // the request, not a long generation.
        std::cout << "sequence reached the pages' end\n";
        break;
      }
      logits = prefill(backend, model, target.get(), operators, pages, pageIds, tokens, decodeArena, seconds);
    }
    double total = 0.0;
    for (double second : seconds) total += second;
    std::cout << "prefills: " << seconds.size() << ", total " << total << " s, mean "
              << (seconds.empty() ? 0.0 : total / seconds.size()) << " s\n";
    std::ofstream ids(argv[3] + std::string(".out"));
    for (const uint32_t token : tokens) ids << token << '\n';
    std::cout << "ripple-real-test: PASS\n";
    return 0;
  } catch (const std::exception &error) {
    std::cerr << "ripple-real-test: FAIL: " << error.what() << '\n';
    return 1;
  }
}
